     if ii not in cc:rows[ii].add(jj)
     cc[ii]=z
    elif ii in cc:
     del cc[ii];rows[ii].discard(jj)
   if cc:heapq.heappush(heap,(len(cc),jj))
  for ii in c:rows[ii].discard(j)
  c.clear();count+=1
 return count
